infra.infra/prod/main.tf:
terraform {
  backend "s3" {}
}
locals {
  names = toset(["a", "b"])
}
resource "aws_kms_key" "k" {
  for_each = local.names
}
resource "aws_s3_bucket" "b" {
  for_each = local.names
  bucket   = "data-${each.key}"
}
resource "aws_s3_bucket_server_side_encryption_configuration" "e" {
  for_each = local.names
  bucket   = aws_s3_bucket.b[each.key].bucket
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.k[each.key].arn
    }
  }
}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = "{}"
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.r.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "s3:GetObject", Resource = "arn:aws:s3:::data-b/*" }, { Effect = "Allow", Action = "kms:Decrypt", Resource = aws_kms_key.k["a"].arn }] })
}
